metrics={'cases_planned':9,'cases_executed':9,**{s:sum(x['status']==s for x in rows) for s in ['PASS','FAIL','PARTIAL','NOT RUN']},**{s:sum(x['unresolved_severities'][s] for x in rows) for s in ['Critical','High','Medium','Low']}}
metrics.update(independent_verification_coverage=100*sum(x['independent_verification']=='PASS' for x in rows)/9,fault_sensitivity_coverage=100*sum(f['result']=='PASS' for x in rows for f in x['fault_variants'])/19,first_pass_success_rate=100*sum(x['first_pass_result']=='PASS' and x['initial_independent_verification']=='PASS' and x['ai_remediation_cycles']==0 for x in rows)/9,final_success_rate=100*metrics['PASS']/9,human_correction_rate=100*sum(x['human_correction'] for x in rows)/9,average_ai_remediation_cycles=sum(x['ai_remediation_cycles'] for x in rows)/9,independent_defect_rate=100*sum(x['independent_findings']>0 for x in rows)/9,scope_violation_rate=100*sum(x['scope_violation'] for x in rows)/9,architecture_correction_rate=100*sum(x['architecture_correction'] for x in rows)/9,initial_independent_clean_pass_rate=100*sum(x['initial_independent_verification']=='PASS' for x in rows)/9,mandatory_faults_planned=19,mandatory_faults_detected=sum(f['result']=='PASS' for x in rows for f in x['fault_variants']),ai_remediation_cycles_total=sum(x['ai_remediation_cycles'] for x in rows),shared_remediation_cycles=0)
# Coordinator decision requires final integrity record before aggregate publication.
