recommendation='CONTROLLED PILOT READY' if valid and metrics['PASS']==9 and not(metrics['Critical'] or metrics['High']) else 'NOT READY'
weaknesses=['PostgreSQL not executed; target-engine validation required before PostgreSQL pilot.','One scaffold and exact fault bindings limit transferability; no greenfield or general autonomy claim.','One BE-001 implementation defect required AI self-remediation; human and Audit gates remain before real use.']
strengths=['All nine original cases independently verified with separate Security review.','All 19 mandatory faults detected, including persistence, unbounded reads and candidate-owned security tests.','Governed inputs, historical evidence and frozen candidates preserved with verifiable raw evidence.']
data={'campaign_id':'BACKEND-EVAL-004','campaign_validity':'VALID' if valid else 'INVALID','foundation_version':'0.6.1','recommendation':recommendation,'metrics':metrics,'metric_definitions':'campaign/metric-definitions.md','denominators':{'planned':9,'executed':9,'initially_evaluated':9,'independently_reviewed':9,'mandatory_faults':19},'postgresql_validation':'NOT EXECUTED','postgresql_target_engine_validation':'REQUIRED BEFORE POSTGRESQL PILOT','production_deployment':'NOT AUTHORIZED','autonomous_production_operation':'NOT AUTHORIZED','human_review':'REQUIRED; no human code review performed during this AI campaign','security_review':'REQUIRED according to policy; nine campaign reviews completed','audit':'REQUIRED according to policy; not completed by this campaign','independence':'Coordinator-verified execution separation; not cryptographic independence','cases':rows,'top_remaining_weaknesses':weaknesses,'top_strengths':strengths,'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat()}
write(C/'final/eval-results.json',data)
labels=[('Campaign','BACKEND-EVAL-004'),('Campaign Validity',data['campaign_validity']),('Foundation','0.6.1'),('Cases Planned',9),('Cases Executed',9)]+[(k,metrics[k]) for k in ['PASS','FAIL','PARTIAL','NOT RUN','Critical','High','Medium','Low']]+[(label,f'{metrics[k]:.2f}%') for label,k in [('Independent Verification Coverage','independent_verification_coverage'),('Fault Sensitivity Coverage','fault_sensitivity_coverage'),('First-pass Success Rate','first_pass_success_rate'),('Final Success Rate','final_success_rate'),('Human Correction Rate','human_correction_rate')]]+[('Average AI Remediation Cycles',f"{metrics['average_ai_remediation_cycles']:.2f}"),('Independent Defect Rate',f"{metrics['independent_defect_rate']:.2f}%"),('Recommendation',recommendation)]
table='| Metric | Result |\n|---|---|\n'+'\n'.join(f'| {k} | {v} |' for k,v in labels)
(C/'summary/evaluation-summary.md').write_text(f"# BACKEND-EVAL-004 evaluation summary\n\n{table}\n\nAll nine original cases passed; no adapted scenario substituted. All 19 mandatory faults were detected. Security review completed for all nine exact hashes; no unresolved findings. Foundation/framework checks passed (36 evaluation + 8 adapter tests). Historical BACKEND-EVAL-003 remains INVALID.\n\nFirst-pass is conservative 8/9: BE-001 failed implementer tests and was self-corrected once before freeze; initial independent clean verification was 9/9. Average AI cycles = 1/9; no human code corrections. Independent defect rate = reviewed cases with findings / 9. Scope and architecture correction rates: 0/9 each. Human review was not performed.\n\nRecommendation covers supervised work in the tested canonical Laravel/SQLite scope only. Shared scaffold and mutation anchors limit generalization; no greenfield or general autonomy claim. PostgreSQL NOT EXECUTED; target-engine validation REQUIRED BEFORE POSTGRESQL PILOT. Human, Security and Audit policy gates remain. Production deployment, autonomous production operation, Release Candidate and real pilot are not authorized or performed.\n")
areas=[('Functional Reliability','9/9 original PASS; BE-001 needed one pre-freeze correction'),('Security-by-Default','9/9 separate reviews; no unresolved Critical/High'),('Architecture Compliance','Scoped Laravel controller/FormRequest/Gate/Action conventions; no architecture correction'),('Automated Testing','Actual candidate tests and independent framework assertions; raw logs retained'),('Independent Verification','9/9; separate evaluator context, post-fault and fresh-workspace repeats'),('Fault Sensitivity','19/19 mandatory variants detected'),('Governance','VALID; input/history/candidate integrity passed'),('Human Intervention','0 code corrections; human review still required'),('SQLite Coverage','Original nine cases, persisted state, transaction race and fetched-row budgets'),('PostgreSQL Coverage','NOT EXECUTED')]
(C/'final/readiness-assessment.md').write_text('# BACKEND-EVAL-004 readiness assessment\n\nRecommendation: **'+recommendation+'**. This is a readiness recommendation only; no real pilot starts.\n\n| Area | Result |\n|---|---|\n'+'\n'.join(f'| {k} | {v} |' for k,v in areas)+'\n\nAll nine cases meet the stricter initial-suite PASS rule, independent verification and mandatory fault coverage are 100%, evidence gates pass, and no Critical/High findings or human code corrections remain. BE-001 needed one AI correction before freeze; this lowers first-pass success to 88.89%. Results are correlated scaffold-assisted samples, not unconstrained construction, broad penetration testing or a general AI autonomy measure. Readiness applies to supervised canonical Laravel/SQLite work; a different project requires its own context, reviewed adapters and controls.\n\nProduction deployment: NOT AUTHORIZED.\n\nAutonomous production operation: NOT AUTHORIZED.\n\nHuman review: REQUIRED.\n\nSecurity review: REQUIRED according to policy.\n\nAudit: REQUIRED according to policy.\n\nPostgreSQL pilot: target-engine validation required (REQUIRED BEFORE POSTGRESQL PILOT). PostgreSQL NOT EXECUTED.\n\nRemaining risks: single reused scaffold and exact source-bound faults constrain transferability; harness is for inspected synthetic source and not hostile code; SQLite result-row instrumentation does not measure query planner scan cost or PostgreSQL concurrency. No Release Candidate, deployment, production action or historical rescore occurred.\n')
detail=['# BACKEND-EVAL-004 detailed evaluation report',table,'## Methodology\nOriginal specifications → frozen reviewer-owned Laravel adapters → reviewed disposable synthetic candidate → implementer tests/self-review → candidate freeze → separate evaluator clean/fault/rerun/repeat → separate Security review → hashed evidence and schema gate → case decision. All nine original cases executed. No adapted historical scenario substituted, including BE-009.','## Governed inventory and provenance\nFoundation 0.6.1, 283 governed assets; campaign/governed-inventory.json and freeze.json carry external pin. Full input validation before implementation and at execution boundaries. Historical inventory pins 500 files. Contexts /root (coordinator), /root/implementer, /root/evaluator, /root/security have separate tool task IDs and explicit start/completion declarations. Reviewer adopted full frozen copy before implementation. Coordinator-verified execution separation; shared filesystem privileges and hashes do not provide cryptographic independence. Human authorization is not human review or Audit.','## Candidates and reuse\nNine unique candidate source manifests/hashes, scoped diffs and changed-file lists are retained in cases/. Frozen calibration source is the disclosed consuming-project baseline. Backend rewrote scoped case methods or BE-009 assertions; inherited working behavior remains substantial. Results establish behavior of these candidates, not authorship of all baseline behavior or greenfield competence. Frozen candidates never remediated during review. BE-001 first attempt failed before freeze, corrected once; prior failed logs retained.']
for x in rows:
 e=x['evaluation_id'];detail.append(f"## {e}\n\n"+(C/'cases'/e/'case-summary.md').read_text().split('\n',1)[1]+ '\n'+(C/'cases'/e/'test-results.md').read_text().split('\n',1)[1])
detail+=['## Security and intervention metrics\nAll nine Security reviews bind to exact candidate hashes and inspect actual enforcement/source, persisted denied state and evaluator raw results. Zero unresolved Critical/High/Medium/Low findings. Mandatory fault detections are synthetic injected defects, not unresolved candidate findings. Independent defect rate 0/9; human correction 0/9; AI cycles 1/9 (no shared cycle); scope/architecture correction 0/9. First-pass success conservatively 8/9 includes pre-freeze BE-001 failure; initial independent clean pass 9/9. All denominators and overlapping assertion-count caveats in campaign/metric-definitions.md.','## SQLite and PostgreSQL limitations\nSQLite memory databases reset per test; BE-006 also executes genuine two-process races on owned temporary SQLite files. Five races per concurrency invocation; evidence logs retained. BE-007/008 instrument PDO materialized rows, not merely response size, at frozen dataset/page sizes. This does not establish execution-plan scan cost, distributed behavior or other database engines. PostgreSQL NOT EXECUTED. PostgreSQL target-engine validation REQUIRED BEFORE POSTGRESQL PILOT.','## Remaining risks and Foundation improvement candidates\nNo Foundation changes made. Future prospective candidates: add reviewed PostgreSQL target-engine tests, add independent project/scaffold samples with held-out tasks, generalize exact source fault bindings through preapproved project-specific adapters, and provide enforced hostile-code containment before any untrusted execution. These are limitations/opportunities, not invented unresolved security findings. Preserve input freeze, reviewer provenance and mandatory original-case gates in any future campaign.','## Final restrictions\nRecommendation '+recommendation+'. Human review REQUIRED; Security and Audit REQUIRED according to policy. Production deployment and autonomous production operation NOT AUTHORIZED. No Release Candidate or real pilot started; no deployment, merge, push, production/customer data or real-secret access. Historical campaigns/reviews unchanged; BACKEND-EVAL-003 remains INVALID.']
(C/'detailed/evaluation-detailed-report.md').write_text('\n\n'.join(detail)+'\n')
print(json.dumps(metrics,indent=2));print(recommendation)
